 17→ * - health: 'healthy' | 'broken' | 'unknown' - filter by health status
 18→ *
 19→ * Returns:
 20→ * - Top tools by quality score
 21→ * - Top tools by npm downloads
 22→ * - Most executed tools
 23→ * - Recently added tools
 24→ * - Tool category distribution
 25→ */
 26→export async function GET(request: NextRequest) {
 27→  const startTime = Date.now();
 28→
 29→  // Check rate limit
 30→  const rateLimitResponse = checkRateLimit(request);
 31→  if (rateLimitResponse) {
 32→    return rateLimitResponse;
 33→  }
 34→
 35→  try {
 36→    const { searchParams } = new URL(request.url);
 37→    const sortBy = searchParams.get('sortBy') || 'quality';
 38→    const limit = Math.min(Number.parseInt(searchParams.get('limit') || '20', 10), 100);
 39→    const category = searchParams.get('category');
 40→    const healthFilter = searchParams.get('health');
 41→
 42→    const now = new Date();
 43→
 44→    // Build where clause
 45→    const whereClause: Record<string, unknown> = {};
 46→    if (category) {
 47→      whereClause.package = { category };
 48→    }
 49→    if (healthFilter === 'healthy') {
 50→      whereClause.importHealth = 'HEALTHY';
 51→      whereClause.executionHealth = 'HEALTHY';
 52→    } else if (healthFilter === 'broken') {
 53→      whereClause.OR = [{ importHealth: 'BROKEN' }, { executionHealth: 'BROKEN' }];
 54→    } else if (healthFilter === 'unknown') {
 55→      whereClause.OR = [{ importHealth: 'UNKNOWN' }, { executionHealth: 'UNKNOWN' }];
 56→    }
 57→
 58→    // Determine sort order
 59→    let orderBy: Record<string, unknown>[];
 60→    switch (sortBy) {
 61→      case 'downloads':
 62→        orderBy = [{ package: { npmDownloadsLastMonth: 'desc' } }, { qualityScore: 'desc' }];
 63→        break;
 64→      case 'recent':
 65→        orderBy = [{ createdAt: 'desc' }];
 66→        break;
 67→      default:
 68→        orderBy = [{ qualityScore: 'desc' }, { package: { npmDownloadsLastMonth: 'desc' } }];
 69→        break;
 70→    }
 71→
 72→    // For execution sorting, we need a different query
 73→    let tools;
 74→    let executionCounts: Map<string, number> = new Map();
 75→
 76→    if (sortBy === 'executions') {
 77→      // Get execution counts first
 78→      const execGroups = await prisma.simulation.groupBy({
 79→        by: ['toolId'],
 80→        _count: { id: true },
 81→        orderBy: { _count: { id: 'desc' } },
 82→        take: limit * 2, // Get more to account for filtering
 83→      });
 84→
 85→      const toolIds = execGroups.map((g) => g.toolId);
