102→              tier: true,
103→              isOfficial: true,
104→              npmHomepage: true,
105→              npmRepository: true,
106→            },
107→          },
108→        },
109→      });
110→
111→      // Sort by execution count
112→      tools.sort((a, b) => (executionCounts.get(b.id) || 0) - (executionCounts.get(a.id) || 0));
113→    } else {
114→      tools = await prisma.tool.findMany({
