 31→/**
 32→ * useScrollReveal Hook
 33→ *
 34→ * Triggers animations when an element enters the viewport using Intersection Observer.
 35→ * Returns a ref to attach to the element and a boolean indicating visibility.
 36→ *
 37→ * @example
 38→ * ```tsx
 39→ * function MyComponent() {
 40→ *   const { ref, isVisible } = useScrollReveal({ threshold: 0.3 });
 41→ *
 42→ *   return (
 43→ *     <div
 44→ *       ref={ref}
 45→ *       className={isVisible ? 'animate-brutalist-entrance' : 'opacity-0'}
 46→ *     >
 47→ *       Content
 48→ *     </div>
 49→ *   );
 50→ * }
 51→ * ```
 52→ */
 53→export function useScrollReveal<T extends HTMLElement>(
 54→  options: UseScrollRevealOptions = {}
 55→): {
 56→  ref: React.RefObject<T | null>;
 57→  isVisible: boolean;
 58→} {
 59→  const { threshold = 0.2, rootMargin = '-100px', once = true, delay = 0 } = options;
 60→
 61→  const ref = useRef<T>(null);
 62→  const [isVisible, setIsVisible] = useState(false);
 63→  const [hasAnimated, setHasAnimated] = useState(false);
 64→
 65→  useEffect(() => {
 66→    const element = ref.current;
 67→    if (!element) return;
 68→
 69→    // If animation has already happened and once is true, don't re-observe
 70→    if (once && hasAnimated) return;
 71→
